ON [dbo].[ivtf_activity]
WITH EXECUTE AS N'dbo'
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @a VARCHAR(10) =
        CASE WHEN EXISTS(SELECT 1 FROM inserted) AND EXISTS(SELECT 1 FROM deleted) THEN 'UPDATE'
             WHEN EXISTS(SELECT 1 FROM inserted) THEN 'INSERT'
             ELSE 'DELETE' END;

    INSERT INTO mon.dml_audit (event_type, schema_name, table_name, row_count, old_values, new_values)
    SELECT @a, 'dbo', 'ivtf_activity',
        CASE WHEN @a IN ('INSERT','UPDATE') THEN (SELECT COUNT(*) FROM inserted)
             ELSE (SELECT COUNT(*) FROM deleted) END,
        CASE WHEN @a IN ('DELETE','UPDATE') THEN (SELECT d.[actno],[controlno],[customer],[style],[color],[buyer_sku],[store],[beg_date],[end_date],[onhand_qty],[onorder_qty],[sold_qty],[prepack],[buyer_size],[total],[IVTF_ACTIVITY_ID] FROM deleted d FOR JSON PATH) END,
        CASE WHEN @a IN ('INSERT','UPDATE') THEN (SELECT i.[actno],[controlno],[customer],[style],[color],[buyer_sku],[store],[beg_date],[end_date],[onhand_qty],[onorder_qty],[sold_qty],[prepack],[buyer_size],[total],[IVTF_ACTIVITY_ID] FROM inserted i FOR JSON PATH) END;
END;
GO
