AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @a VARCHAR(10) =
        CASE WHEN EXISTS(SELECT 1 FROM inserted) AND EXISTS(SELECT 1 FROM deleted) THEN 'UPDATE'
             WHEN EXISTS(SELECT 1 FROM inserted) THEN 'INSERT'
             ELSE 'DELETE' END;

    INSERT INTO mon.dml_audit (event_type, schema_name, table_name, row_count, old_values, new_values)
    SELECT @a, 'dbo', 'ivtf_lot',
        CASE WHEN @a IN ('INSERT','UPDATE') THEN (SELECT COUNT(*) FROM inserted)
             ELSE (SELECT COUNT(*) FROM deleted) END,
        CASE WHEN @a IN ('DELETE','UPDATE') THEN (SELECT d.[style],[color],[warehouse],[prepack],[ivtf_lot_id],[bin_location],[qty1],[qty2],[qty3],[qty4],[qty5],[qty6],[qty7],[qty8],[qty9],[shipped_qty1],[shipped_qty2],[shipped_qty3],[shipped_qty4],[shipped_qty5],[shipped_qty6],[shipped_qty7],[shipped_qty8],[shipped_qty9],[RECEIVED_DATE],[cost],[logfdetail_id],[qty10],[qty11],[qty12],[shipped_qty10],[shipped_qty11],[shipped_qty12],[cutno],[box],[line],[cut_qty1],[cut_qty2],[cut_qty3],[cut_qty4],[cut_qty5],[cut_qty6],[cut_qty7],[cut_qty8],[cut_qty9],[cut_qty10],[cut_qty11],[cut_qty12],[received],[barcode],[royaltor],[cutdetail_id] FROM deleted d FOR JSON PATH) END,
