IF OBJECT_ID(N'[dbo].[trg_audit_dbo_wfupdate]', 'TR') IS NOT NULL
    DROP TRIGGER [dbo].[trg_audit_dbo_wfupdate];
GO
CREATE TRIGGER [dbo].[trg_audit_dbo_wfupdate]
ON [dbo].[wfupdate]
WITH EXECUTE AS N'dbo'
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @a VARCHAR(10) =
        CASE WHEN EXISTS(SELECT 1 FROM inserted) AND EXISTS(SELECT 1 FROM deleted) THEN 'UPDATE'
             WHEN EXISTS(SELECT 1 FROM inserted) THEN 'INSERT'
             ELSE 'DELETE' END;

    INSERT INTO mon.dml_audit (event_type, schema_name, table_name, row_count, old_values, new_values)
    SELECT @a, 'dbo', 'wfupdate',
        CASE WHEN @a IN ('INSERT','UPDATE') THEN (SELECT COUNT(*) FROM inserted)
             ELSE (SELECT COUNT(*) FROM deleted) END,
        CASE WHEN @a IN ('DELETE','UPDATE') THEN (SELECT d.[filename],[filedata],[wfupdate_id],[updated_date],[memo],[wf_dbname] FROM deleted d FOR JSON PATH) END,
        CASE WHEN @a IN ('INSERT','UPDATE') THEN (SELECT i.[filename],[filedata],[wfupdate_id],[updated_date],[memo],[wf_dbname] FROM inserted i FOR JSON PATH) END;
END;
GO
